create or replace function public.business_update_campaign(p_business_id uuid,p_campaign_id uuid,p_name text,p_campaign_type text,p_goal text,p_status text) returns uuid language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not public.business_can_manage(p_business_id) then raise exception 'Business management access required';end if;if not public.business_advanced_allowed(p_business_id) then raise exception 'Business Growth or Enterprise plan required';end if;update public.enterprise_partner_campaigns c set name=coalesce(nullif(trim(p_name),''),name),campaign_type=coalesce(nullif(trim(p_campaign_type),''),campaign_type),goal=coalesce(p_goal,goal),status=coalesce(nullif(trim(p_status),''),status) where c.id=p_campaign_id and c.network_id in(select id from public.enterprise_partner_networks where owner_business_id=p_business_id);if not found then raise exception 'Campaign not found';end if;return p_campaign_id;end $$; revoke all on function public.business_update_campaign(uuid,uuid,text,text,text,text) from public,anon; grant execute on function public.business_update_campaign(uuid,uuid,text,text,text,text) to authenticated;
